const e=[{id:"portland-screen",packId:"pack_portland_on_screen_v0",title:"Portland On Screen",subtitle:"Film & TV Tour",city:"Portland, OR",price:"$5.00",access:"Paid tour",partner:"Visit Portland",status:"Field review needed",savedOffline:!0,tags:["Film & TV","Driving Loop","30 Stops"],description:"Follow Portland’s film and TV history through Grimm, Portlandia, Twilight, Leverage, Gus Van Sant landmarks, and neighborhood locations. Built from a structured tour pack, then reviewed for route flow, safety, and publishing readiness.",stats:"30 stops · driving route · 6 walkable clusters",color:"orange",colorClass:"bg-orange-600",routeModes:[{id:"driving",label:"Driving Loop",meta:"30 stops · 3.5 hours",recommended:!0},{id:"walking",label:"Walking Clusters",meta:"6 clusters · 45–90 min each"},{id:"transit",label:"Transit-Friendly",meta:"Coming soon"},{id:"audio-ar",label:"Audio AR Mode",meta:"Future proximity layer"}],clusters:["Old Town","Downtown/Park Blocks","Central Eastside","Rose Quarter/Lloyd","N Mississippi","St. Johns"],stops:[{id:"custom-house",number:2,title:"U.S. Custom House",location:"Old Town/Chinatown",production:"Grimm",coordinates:"45.5252, -122.6768",onApproach:"A grand, columned stone building fills the block. Look for the arched ground-floor windows.",atStop:"The 1901 U.S. Custom House stood in for the exterior of Nick and Hank’s police precinct on Grimm. The interiors were built sets, but this gravitas-heavy facade sold the precinct’s authority.",whyItMatters:"A clean example of how a real civic building becomes an anchor for fictional place identity.",safety:"Good sidewalk visibility; avoid blocking building entrances.",offerHint:"Coffee, river walk, parking",audioDuration:"1 min 55 sec"},{id:"bridgeport-brewpub",number:3,title:"BridgePort Brewpub",location:"Pearl District",production:"Leverage",coordinates:"45.5308, -122.6853",onApproach:"Into the Pearl now, to a converted brick warehouse with big brewery windows. Look for the loading-dock frontage.",atStop:"When Leverage moved from playing Boston to openly being Portland in Season 5, the team’s new base was “the back of the BrewPub” — filmed at this brick brewery. Line up the warehouse frontage and picture Nate’s crew running cons out the back.",whyItMatters:"This is the moment the tour starts to feel like a working city map of a TV universe, not just a list of trivia.",safety:"Urban sidewalk stop. Watch bike lanes and loading zones while framing photos.",offerHint:"Coffee, lunch, parking",audioDuration:"2 min 45 sec"},{id:"jakes-crawfish",number:6,title:"Jake’s Famous Crawfish",location:"West End / Downtown",production:"My Own Private Idaho",coordinates:"45.5225, -122.6835",onApproach:"On the corner of 12th and Stark, look for the old white-tiled seafood house and classic neon sign.",atStop:"Jake’s Famous Crawfish, open since 1892, appears in exterior shots of Gus Van Sant’s My Own Private Idaho. Frame the corner and vintage signage — one of the few locations that still feels close to its 1991 screen texture.",whyItMatters:"It links Portland’s restaurant history with the city’s indie-film mythology.",safety:"Busy downtown corner. Cross only at signals.",offerHint:"Dinner reservation, cocktails, hotel bar",audioDuration:"2 min 10 sec"},{id:"burnside-skatepark",number:10,title:"Burnside Skatepark",location:"Central Eastside",production:"Paranoid Park",coordinates:"45.5231, -122.6637",onApproach:"Cross the river and tuck under the east end of the Burnside Bridge. Listen for wheels on concrete.",atStop:"Burnside Skatepark was built illegally by skaters in 1990 and later accepted by the city. Gus Van Sant used its DIY concrete energy as part of the emotional world of Paranoid Park.",whyItMatters:"This is place as subculture: a real community-built environment that film could not fake.",safety:"Active skate area. Stay clear of lines and do not stand in bowls.",offerHint:"Coffee, food carts, bridge walk",audioDuration:"2 min 30 sec"},{id:"land-gallery",number:19,title:"Land Gallery",location:"N Mississippi",production:"Portlandia",coordinates:"45.5513, -122.6758",onApproach:"Onto Mississippi Avenue: boutiques, makers, restaurants, and small storefronts packed into a walkable strip.",atStop:"Land Gallery is where Portlandia’s “Put a Bird on It” sketch was filmed. The joke was tiny, but it became shorthand for a whole era of Portland self-image.",whyItMatters:"A consumer-friendly stop that converts instantly into shopping, food, and neighborhood exploration intent.",safety:"Easy walking cluster; watch curb cuts and parked bikes.",offerHint:"Shopping, brunch, coffee",audioDuration:"1 min 40 sec"},{id:"st-johns-bridge",number:22,title:"St. Johns Bridge",location:"St. Johns",production:"My Own Private Idaho / Paranoid Park",coordinates:"45.5853, -122.7645",onApproach:"The green Gothic towers rise over the river like a cathedral. For the best view, drop toward Cathedral Park.",atStop:"The St. Johns Bridge appears in both My Own Private Idaho and Paranoid Park. Its pointed towers and under-bridge arches give Portland one of its most cinematic built environments.",whyItMatters:"A spectacular visual payoff stop, and a natural anchor for a St. Johns neighborhood cluster.",safety:"Use designated viewpoints; do not stop on the bridge shoulder.",offerHint:"Brewpubs, Cathedral Park, coffee",audioDuration:"2 min 20 sec"},{id:"cullen-house",number:25,title:"Cullen House / Hoke House",location:"West Hills",production:"Twilight",coordinates:"45.4930, -122.7130",warning:"Private residence — drive-by only",onApproach:"Deeper in the West Hills, a striking glass-and-timber modern house steps down a wooded slope.",atStop:"The Robert Oshatz-designed Hoke House was the Cullen family home in Twilight. This must remain a respectful drive-by from the public road: do not approach, block the lane, or publish directions that encourage trespass.",whyItMatters:"A perfect example of why Tour Engine needs publishability guardrails, not just exciting content.",safety:"Private residence. No stopping, no trespassing, no geofence-triggered crowding.",offerHint:"Nearby viewpoint, coffee after route",audioDuration:"1 min 35 sec"}]},{id:"oahu-screen",packId:"pack_oahu_on_screen_v1",title:"Oʻahu On Screen",subtitle:"Jurassic & Beyond",city:"Honolulu, HI",price:"Free sample",access:"Free sample",tags:["Film & TV","Nature"],color:"emerald",colorClass:"bg-emerald-700"},{id:"osaka-food-night",packId:"pack_osaka_food_night_fieldtest_v0",title:"Osaka Food Night Field Test",subtitle:"Dōtonbori → Kuromon → Shinsekai",city:"Osaka, JP",price:"Field test",access:"Private preview",partner:"808Alpha Travel Lab",status:"Field test only",savedOffline:!0,tags:["Food","Walking","Field Test","Japan"],description:"A compact Osaka field-test route for validating Tour Engine as local business discovery: high-density food streets, visitor intent, and contextual offer moments. Content and coordinates require field verification before publishing.",stats:"5 stops · walking route · food/night focus",color:"red",colorClass:"bg-red-700",routeModes:[{id:"walking",label:"Walking Field Test",meta:"5 stops · flexible timing",recommended:!0},{id:"transit",label:"Transit Assist",meta:"Use subway between clusters if tired"}],clusters:["Namba","Dōtonbori","Kuromon","Nipponbashi","Shinsekai"],stops:[{id:"dotonbori-glico",number:1,title:"Dōtonbori / Glico Sign",location:"Dōtonbori canal",production:"Osaka food culture",coordinates:"34.6687, 135.5013",warning:"High-crowd area — field-test timing and navigation clarity",onApproach:"Enter the neon canyon around the canal. Use the Glico sign as the visual anchor, then notice how food signs, bridges, and crowds create Osaka’s “eat here now” energy.",atStop:"This is the obvious visitor-intent moment: people are already hungry, photographing signs, and deciding what to try next. Tour Engine should turn that intent into useful nearby guidance, not generic ads.",whyItMatters:"Dōtonbori is the stress test for context: the app must help without adding friction in a crowded, stimulus-heavy place.",safety:"Stay out of pedestrian flow; do not stop in the middle of bridge approaches. Watch bags and phones in crowds.",offerHint:"Takoyaki, okonomiyaki, dessert, late-night snacks",audioDuration:"1 min 30 sec"},{id:"hozenji-yokocho",number:2,title:"Hozenji Yokocho",location:"Namba side street",production:"Quiet contrast",coordinates:"34.6679, 135.5022",onApproach:"Step away from the neon into a narrow stone lane. The sensory shift is the point: from spectacle to intimacy in just a few turns.",atStop:"Hozenji Yokocho tests whether a route can slow someone down. This is where narration should be short, respectful, and useful — not a lecture.",whyItMatters:"A good local tour needs rhythm: loud stop, quiet stop, food stop, reflection stop.",safety:"Narrow lanes; keep moving if groups are passing. Be respectful around temple space.",offerHint:"Small bars, dinner reservation, dessert nearby",audioDuration:"1 min 15 sec"},{id:"kuromon-market",number:3,title:"Kuromon Ichiba Market",location:"Nipponbashi",production:"Osaka’s kitchen",coordinates:"34.6647, 135.5063",warning:"Business mix/hours vary — verify day-of relevance",onApproach:"Walk toward covered market streets and food counters. Look for the shift from restaurant district to ingredient-and-snack marketplace.",atStop:"Kuromon is a clean business-layer test: the tour can explain why this market matters while surfacing one or two useful food prompts nearby.",whyItMatters:"This stop shows whether local business discovery can feel native to the route instead of bolted on.",safety:"Crowded market aisles. Buy only where lines and signage make sense; avoid blocking stalls.",offerHint:"Seafood snack, fruit, coffee break",audioDuration:"1 min 45 sec"},{id:"nipponbashi-den-den",number:4,title:"Nipponbashi Den Den Town",location:"Nipponbashi",production:"Otaku/electronics retail",coordinates:"34.6598, 135.5067",onApproach:"As you move south, the food-market energy gives way to electronics, hobby shops, figures, games, and specialty retail.",atStop:"This is a non-food commerce test. The question is whether Tour Engine can match route theme, user interest, and merchant relevance without feeling like a coupon directory.",whyItMatters:"A marketplace around tours should support more than restaurants — shops, attractions, museums, services, and experiences all matter.",safety:"Standard urban walking; pause near storefront edges, not in crossing paths.",offerHint:"Anime goods, retro games, café stop",audioDuration:"1 min 20 sec"},{id:"shinsekai-tsutenkaku",number:5,title:"Shinsekai / Tsūtenkaku",location:"Shinsekai",production:"Retro Osaka",coordinates:"34.6525, 135.5063",warning:"Evening vibe varies by block — field-test comfort and lighting",onApproach:"Approach the tower and look for the retro signs, kushikatsu storefronts, and older entertainment-district texture.",atStop:"Shinsekai is where the route can end with a strong identity: older Osaka, food ritual, and a clear “what should I do now?” business moment.",whyItMatters:"The final stop should convert exploration into a meal, a memory, or a save-for-later action.",safety:"Use normal city awareness at night. Keep the route manual-first; do not imply automated safety guidance.",offerHint:"Kushikatsu, tower ticket, coffee after walk",audioDuration:"1 min 50 sec"}]},{id:"osaka-camera-crawl",packId:"pack_osaka_camera_crawl_fieldtest_v0",title:"Osaka Camera Store Crawl Field Test",subtitle:"Umeda → Shinsaibashi → Namba → Den Den Town",city:"Osaka, JP",price:"Field test",access:"Private preview",partner:"808Alpha Travel Lab",status:"Field test only",savedOffline:!0,tags:["Photography","Shopping","Walking","Field Test","Japan"],description:"A practical Osaka camera-shop route for testing Tour Engine as high-intent retail discovery: compare new gear, used/vintage inventory, tax-free shopping, repair/print services, and specialty electronics streets. Store hours, stock, tax-free rules, and coordinates require field verification before publishing.",stats:"5 stops · transit-assisted shopping route · camera gear focus",color:"purple",colorClass:"bg-purple-800",routeModes:[{id:"transit",label:"Transit-Assisted Field Test",meta:"Umeda to Namba/Shinsaibashi clusters",recommended:!0},{id:"walking",label:"South Cluster Walk",meta:"Shinsaibashi → Namba → Den Den Town"}],clusters:["Umeda","Shinsaibashi","Namba","Nipponbashi","Den Den Town"],stops:[{id:"yodobashi-umeda-camera",number:1,title:"Yodobashi Camera Multimedia Umeda",location:"Umeda / Osaka Station area",production:"Big-box baseline",coordinates:"34.7044, 135.4965",warning:"Large store and station complex — verify entrances, floor layout, and tax-free counter flow",onApproach:"Start at the big-box anchor near Osaka Station. Treat this as the baseline for price, availability, language support, accessories, and tax-free process before comparing smaller shops.",atStop:"This stop tests whether a commerce tour can help a traveler shop smarter without becoming a generic directory. The useful action is not “buy here”; it is “understand the baseline before hunting.”",narrationScripts:{japaneseFemale:"ここでは、カメラ店めぐりがただのお店リストではなく、買い物の判断を助けられるかをテストします。大事なのは「ここで買う」ではなく、まず価格、在庫、アクセサリー、免税の流れを知ることです。",japaneseMale:"ここでは、カメラ店めぐりがただのお店リストではなく、買い物の判断を助けられるかをテストします。大事なのは「ここで買う」ではなく、まず価格、在庫、アクセサリー、免税の流れを知ることです。"},whyItMatters:"Camera shoppers are high-intent, comparison-heavy, and time-constrained. A good route can turn scattered research into a practical buying path.",safety:"Busy station area. Keep the phone away while crossing and avoid stopping in escalator/stair flows.",offerHint:"Tax-free checklist, accessory reminder, price comparison note",audioDuration:"16 sec"},{id:"camera-naniwa-shinsaibashi",number:2,title:"Camera no Naniwa Shinsaibashi",location:"Shinsaibashisuji area",production:"Used/vintage specialty",coordinates:"34.6740, 135.5018",warning:"Verify exact floor, hours, used inventory policies, and English support before publishing",onApproach:"Move into the Shinsaibashi shopping area and look for the shift from department-store retail to specialist camera browsing.",atStop:"This is the route’s used-gear intelligence stop. The field-test question: does the app help you inspect condition, price, compatibility, warranty, and return constraints quickly enough to be useful?",whyItMatters:"Specialty used-camera shops are where a route can add real value: checklists, translation prompts, comparison memory, and save-for-later evidence.",safety:"Dense shopping street. Step aside before checking notes or prices.",offerHint:"Used lens checklist, film-camera note, save-for-later comparison",audioDuration:"1 min 45 sec"},{id:"bic-camera-namba",number:3,title:"Bic Camera Namba",location:"Namba / Sennichimae area",production:"Tax-free big-box comparison",coordinates:"34.6656, 135.5011",warning:"Verify tax-free rules, coupons, payment options, and current camera floor before relying on this stop",onApproach:"Use Namba as the second big-box comparison point. You are now close to food, transit, and Den Den Town, so the route shifts from baseline research to purchase decision support.",atStop:"This is where Tour Engine can test “decision assistance”: compare price, tax-free friction, accessories, and whether the traveler should buy now or continue to used/specialty shops.",whyItMatters:"Retail intent is measurable. A route that helps people decide where not to buy is often more trusted than one that only pushes conversion.",safety:"Busy intersection and shopping area. Avoid looking down at the phone while entering/exiting crowds.",offerHint:"Tax-free reminder, accessory bundle prompt, price-check note",audioDuration:"1 min 25 sec"},{id:"namba-camera-service-check",number:4,title:"Namba Camera Service / Print Check",location:"Namba station retail cluster",production:"Service and practical needs",coordinates:"34.6639, 135.5019",warning:"Placeholder service stop — verify current store presence, hours, and services before publishing",onApproach:"Before heading into Den Den Town, check whether the route should support practical services: batteries, SD cards, prints, used trade-in, passport photos, repairs, or cleaning.",atStop:"This stop is intentionally utilitarian. Not every commerce route needs a famous shop; sometimes the most valuable moment is solving a small travel problem fast.",whyItMatters:"Local business discovery is not just offers. It is service matching at the moment of need.",safety:"Station/underground retail can be disorienting. Verify signage and exits during field testing.",offerHint:"SD card, battery, print, cleaning, repair, trade-in",audioDuration:"1 min 10 sec"},{id:"den-den-town-camera-gear",number:5,title:"Nipponbashi / Den Den Town Camera Gear Walk",location:"Nipponbashi electronics district",production:"Specialty retail finish",coordinates:"34.6598, 135.5067",warning:"Store mix changes — field-verify actual camera relevance block-by-block",onApproach:"End in the electronics/hobby retail district. Look for used electronics, accessories, adapters, tripods, bags, lighting, and specialty gear rather than one single destination.",atStop:"This is the discovery finish: the route should help camera shoppers browse with intent, save promising stops, and capture what felt useful versus spammy.",whyItMatters:"A strong local-commerce route should create serendipity without losing the buyer’s mission.",safety:"Standard urban shopping-street awareness. Watch crossings and keep purchases secure.",offerHint:"Used accessories, adapters, camera bags, lighting, specialty gear",audioDuration:"1 min 40 sec"}]},{id:"kobe-kitano-harbor",packId:"pack_kobe_kitano_harbor_fieldtest_v0",title:"Kobe Story Walk Field Test",subtitle:"Kitano → Nankinmachi → Harborland",city:"Kobe, JP",price:"Field test",access:"Private preview",partner:"808Alpha Travel Lab",status:"Field test only",savedOffline:!0,tags:["Culture","Food","Walking","Field Test","Japan"],description:"A Kobe field-test route for story-rich neighborhoods, café/retail relevance, food discovery, and waterfront pacing. Content and coordinates require field verification before publishing.",stats:"5 stops · walking/transit route · culture + food + waterfront",color:"blue",colorClass:"bg-blue-700",routeModes:[{id:"walking",label:"Walking Field Test",meta:"5 stops · use transit/taxi if needed",recommended:!0},{id:"split",label:"Split Route",meta:"Kitano first, harbor later"}],clusters:["Kitano","Sannomiya","Nankinmachi","Meriken Park","Harborland"],stops:[{id:"kitano-ijinkan",number:1,title:"Kitano Ijinkan District",location:"Kitano-cho",production:"Port city history",coordinates:"34.7009, 135.1897",warning:"Hills/stairs — verify accessibility notes",onApproach:"Climb gently into Kitano and look for Western-style houses, cafés, and hillside streets at the foot of the Rokko range.",atStop:"Kitano exists because Kobe opened as an international port in the 19th century. For Tour Engine, this is a story-rich neighborhood where cafés and small shops can belong naturally to the route.",whyItMatters:"This tests whether commerce can attach to atmosphere and history, not just hunger.",safety:"Hilly streets and stairs. Watch footing, especially in rain.",offerHint:"Café, museum ticket, boutique stop",audioDuration:"1 min 45 sec"},{id:"sannomiya-crossing",number:2,title:"Sannomiya Orientation Stop",location:"Sannomiya",production:"City center transition",coordinates:"34.6947, 135.1950",onApproach:"Move back toward the city’s transport and shopping center. This is the connective tissue between hillside Kobe and waterfront Kobe.",atStop:"A good field-test route needs practical orientation stops, not just attractions. This stop should answer: where am I, what is nearby, and what should I do next?",whyItMatters:"Orientation is product utility. It is also where hotels and transit-adjacent businesses may matter.",safety:"Busy station-area crossings. Follow signals and avoid stopping in commuter paths.",offerHint:"Coffee, locker, transit, shopping",audioDuration:"1 min 10 sec"},{id:"nankinmachi",number:3,title:"Nankinmachi",location:"Kobe Chinatown",production:"Food district",coordinates:"34.6887, 135.1878",warning:"Crowded food area — verify best approach and business relevance",onApproach:"Look for the gate, lanterns, food counters, and compact streets. The pace changes again: this is browsing, snacking, and choosing.",atStop:"Nankinmachi is the Kobe equivalent of a high-intent offer test. The app should help pick one useful next action without overwhelming the walk.",whyItMatters:"This is where local-business discovery can become immediately measurable.",safety:"Crowds and food lines. Step aside before reading/listening.",offerHint:"Snack, tea, dessert, nearby dinner",audioDuration:"1 min 30 sec"},{id:"meriken-park",number:4,title:"Meriken Park",location:"Waterfront",production:"Harbor identity",coordinates:"34.6826, 135.1885",onApproach:"Walk toward open waterfront space, port views, public art, and Kobe’s harbor skyline.",atStop:"Meriken Park changes the route from dense streets to breathing room. This is where the product should reduce screen time and let the place carry the moment.",whyItMatters:"The app should know when not to overtalk. Good pacing is part of the product.",safety:"Open public space; watch weather/wind and waterfront edges.",offerHint:"Photo stop, museum, harbor café",audioDuration:"1 min 25 sec"},{id:"harborland",number:5,title:"Harborland / Mosaic",location:"Kobe Harborland",production:"Evening waterfront",coordinates:"34.6784, 135.1835",onApproach:"Continue along the waterfront toward shops, restaurants, and evening lights.",atStop:"Harborland is a natural closing conversion point: dinner, shopping, coffee, view, or save-for-later. The question is whether a route can drive a useful business visit at the right moment.",whyItMatters:"This is the DMO/hotel pitch in miniature: visitor experience plus measurable local economic activity.",safety:"Standard waterfront/shopping-area awareness. Verify late hours before relying on specific businesses.",offerHint:"Dinner, Kobe sweets, harbor cruise, coffee",audioDuration:"1 min 40 sec"}]},{id:"tokyo-rain",packId:"pack_tokyo_rainy_day_v0",title:"Tokyo Rainy-Day",subtitle:"Culture Walk",city:"Tokyo, JP",price:"$8.00",access:"Paid tour",tags:["Architecture","Walking"],color:"teal",colorClass:"bg-teal-700"},{id:"downtown-loop",packId:"pack_portland_food_history_v0",title:"Downtown Food & History Loop",subtitle:"Culinary Origins",city:"Portland, OR",price:"$12.00",access:"Bundle eligible",tags:["Food","History"],color:"purple",colorClass:"bg-purple-800"}],t=["All","Film & TV","Food","Photography","Shopping","History","Architecture","Family","Accessible","Free Sample"];export{t as f,e as t};
